        if (current_day > next_interview) {
            caffeine_count++;
            interview_index++;
            continue;
        }

        // Calculate how many full cycles we can skip
        int days_to_interview = next_interview - current_day;
        int cycle_sum = 0;
        for (int i = 0; i < n; i++) {
            cycle_sum += sleep_cycle[i];
        }

        if (cycle_sum > 0 && days_to_interview / cycle_sum > 0) {
            int skip_cycles = days_to_interview / cycle_sum;
            current_day += skip_cycles * cycle_sum;
            // cycle_index remains the same since we skip full cycles
        }

        // Now simulate day by day until we reach or pass the interview
        while (current_day <= next_interview && interview_index < m) {
            // If current day is an interview day
            if (current_day == next_interview) {
                // Check if Peter is awake (sleep hour <= 1 means he's awake after first hour)
                // Actually, Peter sleeps for sleep_cycle[cycle_index] hours.
                // He is awake for the rest of the day after sleeping.
                // The problem states he needs to wake up on time for interviews.
                // If he sleeps through the interview, he needs caffeine.
                // He will be awake if the interview is after his sleep period.
                // Since we don't know exact interview time, we assume if he sleeps
                // on that day, he might miss it. To be safe, we give caffeine
                // if he sleeps at all that day (sleep hours > 0).
                // But the problem likely means: if he sleeps during the interview hour,
                // he needs caffeine. Since no specific hour is given, 
                // we assume any sleep on interview day requires caffeine.
                // However, typical interpretation: if he sleeps more than 0 hours,
