#include <stdio.h>

int is_sleeping(int t) {
    // t is 1-indexed hour
    // Cycle k: hours from sum(2*1..k-1)+1 to sum(2*1..k)
    // sum of 2*i for i=1 to k = k*(k+1)
    // Cycle k spans hours k*(k-1)+1 to k*(k+1)
    // First k hours of cycle = sleep, next k hours = awake
    int k = 1;
    int start = 1;
    while (start + 2*k - 1 < t) {
        start += 2*k;
        k++;
    }
    // t is in cycle k, starting at 'start'
    int pos = t - start + 1; // position within cycle (1-indexed)
    return pos <= k; // first k positions are sleep
}

