int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    long long *sleep = (long long *)malloc((n + 1) * sizeof(long long));
    long long *pref = (long long *)malloc((n + 1) * sizeof(long long));
    long long *interviews = (long long *)malloc(m * sizeof(long long));

    if (!sleep || !pref || !interviews) return 0;

    sleep[0] = 0;
    pref[0] = 0;

    for (int i = 1; i <= n; i++) {
        scanf("%lld", &sleep[i]);
        pref[i] = pref[i - 1] + sleep[i];
    }

    for (int i = 0; i < m; i++) scanf("%lld", &interviews[i]);

    int ans = 0;
    int day = 1;  // current day in cycle, starts from day 1

    for (int i = 0; i < m; i++) {
        long long t = interviews[i];

        // If interview time is earlier than or equal to current day's wake-up threshold,
        // Peter must take caffeine before this interview.
        if (t <= pref[day]) {
            ans++;
            day = 1;
            continue;
        }

        // Find the smallest d such that pref[d] >= t
        int l = 1, r = n, res = n;
        while (l <= r) {
            int mid = (l + r) / 2;
            if (pref[mid] >= t) {
                res = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        day = res;
    }

    printf("%d\n", ans);

    free(sleep);
    free(pref);
    free(interviews);
    return 0;
}

