import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = fs.nextLong();

        int m = fs.nextInt();
        long[] t = new long[m];
        for (int i = 0; i < m; i++) t[i] = fs.nextLong();

        // Prefix sums of Peter's natural wake-up times after each sleep segment.
        long[] pref = new long[n];
        pref[0] = a[0];
        for (int i = 1; i < n; i++) pref[i] = pref[i - 1] + a[i];

        long cycle = pref[n - 1];

        int ans = 0;
        long lastAwake = 0; // time when caffeine last reset his schedule

        for (long interview : t) {
            long elapsed = interview - lastAwake;

            // Find first natural wake-up time >= elapsed
            long rem = elapsed % cycle;
            long cyclesBefore = elapsed / cycle;
            if (rem == 0) {
                rem = cycle;
                cyclesBefore--;
            }

            int idx = Arrays.binarySearch(pref, rem);
            if (idx < 0) idx = -idx - 1;

            long wakeTime = lastAwake + cyclesBefore * cycle + pref[idx];

            if (wakeTime != interview) {
                ans++;
                lastAwake = interview;
            }
        }

        System.out.println(ans);
    }
}

